/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random } from '../remotionShim';
// Schema Definition - Prop names preserved as per strict rules, default values adapted


export type JltvSceneProps = Record<string, any>;

const JltvScene: React.FC<JltvSceneProps> = ({
  backgroundColor = "#B3C6D3", // Sky blue/grey
  transparentBackground = false,
  durationInSeconds = 10,
  vehicleColor = "#4A5D6B", // Navy boat grey
  waveColor = "rgba(255, 255, 255, 0.9)",
  droneColor = "#FFD700", // Yellow drone color
  terrainColor = "rgba(10, 50, 100, 0.15)", // Ocean water lines
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Base Values
  const boatSpeed = 4;
  const boatBounce = Math.sin(frame * 0.3) * 3; // Boats bob slower and deeper

  // Scene Coordinates
  const boatX = width * 0.3 + frame * boatSpeed;
  const boatY = height * 0.7; // Sitting slightly lower in the water
  
  // Radar is mounted to the cabin roof (-90 offset) and its pivot is at -50
  const radarOriginY = boatY - 140;

  // Render the animated 3D wireframe ocean
  const renderOcean = () => {
    const linesCount = 30; // Denser lines for water
    const spacing = 20;

    return (
      <g style={{ transition: "none" }}>
        {Array.from({ length: linesCount }).map((_, i) => {
          const baseY = height * 0.55 + i * spacing;
          const perspectiveScale = Math.max(0, (baseY - height * 0.55) / (height * 0.45));
          
          let d = "";
          for (let x = 0; x <= width + 200; x += 100) {
            // Enhanced frame interpolation to make the water visibly rush past the boat
            const timeOffset = frame * 0.1;
            const boatParallax = frame * boatSpeed * 2.5; 
            const sampleX = x + boatParallax;
            
            const wave = (
              Math.sin(sampleX * 0.005 + i + timeOffset) + 
              Math.cos(sampleX * 0.008 + i * 0.5 + timeOffset * 1.5)
            ) * 40 * perspectiveScale;
            
            if (x === 0) {
              d = `M 0 ${baseY + wave}`;
            } else {
              d += ` L ${x} ${baseY + wave}`;
            }
          }

          return (
            <path
              key={`ocean-line-${i}`}
              d={d}
              fill="none"
              stroke={terrainColor}
              strokeWidth={1 + perspectiveScale * 2.5}
            />
          );
        })}
      </g>
    );
  };

  // Render the Military Boat Profile
  const renderBoat = () => {
    // Device rotates from -35 (backwards) to 35 (forwards) between frames 110 and 140
    const deviceRotation = interpolate(frame, [110, 140], [-35, 35], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

    return (
      <g transform={`translate(${boatX}, ${boatY + boatBounce})`} style={{ transition: "none" }}>
        
        {/* Dynamic Wake Trail */}
        {Array.from({ length: 3 }).map((_, i) => (
          <path
            key={`wake-${i}`}
            d={`M -150,20 Q -${250 + i * 40},${20 + Math.sin(frame * 0.1 + i) * 15} -${350 + i * 50},${25 + i * 5} Q -250,${30 + Math.cos(frame * 0.15 + i) * 10} -150,25 Z`}
            fill="rgba(255, 255, 255, 0.4)"
            opacity={1 - i * 0.3}
          />
        ))}

        {/* Bow Splash */}
        <circle cx="110" cy="20" r={4 + Math.sin(frame * 0.5) * 2} fill="white" opacity={0.7} />
        <circle cx="120" cy="18" r={3 + Math.cos(frame * 0.4) * 2} fill="white" opacity={0.5} />

        {/* --- Hull --- */}
        <polygon
          points="-160,20 120,20 180,-30 -170,-30"
          fill={vehicleColor}
          stroke="#2A3028"
          strokeWidth={2}
        />
        <polygon points="-170,-30 -160,-40 -150,-30" fill="#2E342B" />
        <line x1="-150" y1="5" x2="110" y2="5" stroke="#2A3028" strokeWidth={1} opacity={0.5} />

        {/* --- Cabin --- */}
        <polygon
          points="-80,-30 -40,-90 40,-90 70,-30"
          fill="#313E47"
          stroke="#2A3028"
          strokeWidth={2}
        />

        {/* --- Windows --- */}
        <polygon points="-30,-80 0,-80 0,-40 -60,-40" fill="#151B17" />
        <polygon points="10,-80 35,-80 55,-40 10,-40" fill="#151B17" />

        {/* --- Top Device (Radar/Jammer) --- */}
        <g transform="translate(-10, -90)">
          {/* Base Mount */}
          <rect x="-10" y="-30" width="20" height="30" fill="#2A3028" />
          <polygon points="-15,-30 15,-30 5,-50 -5,-50" fill="#222620" />
          
          {/* Angled Emitter Panel (Swivels based on current frame sequence) */}
          <g transform={`translate(0, -50) rotate(${deviceRotation})`}>
            <rect x="-10" y="-80" width="20" height="90" fill="#222620" rx={2} />
            <rect x="-8" y="-75" width="16" height="80" fill="#151B17" />
            <line x1="-10" y1="-30" x2="10" y2="-30" stroke="#323830" strokeWidth={2} />
            <line x1="-10" y1="-50" x2="10" y2="-50" stroke="#323830" strokeWidth={2} />
          </g>
        </g>
      </g>
    );
  };

  // Render Emitting Radar Waves (Both directions sequenced)
  const renderWaves = () => {
    const waveCount = 7;
    const waveDuration = 180; // frames per wave cycle

    const renderWaveGroup = (direction: "left" | "right", activeStartFrame: number, activeEndFrame: number) => {
      return Array.from({ length: waveCount }).map((_, i) => {
        const progress = ((frame + (i * waveDuration) / waveCount) % waveDuration) / waveDuration;
        const age = progress * waveDuration;
        
        const emissionFrame = frame - age;
        
        // Only render waves that were emitted within this group's active window
        if (emissionFrame < activeStartFrame || emissionFrame > activeEndFrame) return null;

        const emissionBoatX = width * 0.3 + emissionFrame * boatSpeed;
        const emissionBounce = Math.sin(emissionFrame * 0.3) * 3;
        
        // Offset relative to the boat's center (-10 is radar base offset)
        const emissionRadarOriginX = direction === "left" ? emissionBoatX - 30 : emissionBoatX + 10;

        const easeOutQuad = 1 - (1 - progress) * (1 - progress);
        const radius = interpolate(easeOutQuad, [0, 1], [10, 350]);
        
        const targetX = direction === "left" ? emissionRadarOriginX - 600 : emissionRadarOriginX + 600;
        const currentX = interpolate(progress, [0, 1], [emissionRadarOriginX, targetX]);
        const currentY = interpolate(progress, [0, 1], [radarOriginY + emissionBounce, radarOriginY - 300]);
        
        const opacity = interpolate(progress, [0, 0.05, 0.7, 1], [0, 1, 0.5, 0]);

        return (
          <circle
            key={`wave-${direction}-${i}`}
            cx={currentX}
            cy={currentY}
            r={radius}
            fill="none"
            stroke={waveColor}
            strokeWidth={interpolate(progress, [0, 1], [5, 1])}
            opacity={opacity}
          />
        );
      });
    };

    return (
      <g style={{ transition: "none" }}>
        {/* First blast goes backwards until frame 120 */}
        {renderWaveGroup("left", -180, 120)}
        {/* Second blast goes forwards starting at frame 130 */}
        {renderWaveGroup("right", 130, 999)}
      </g>
    );
  };

  // Render Swarm of Drones Falling into the Ocean
  const renderDrones = () => {
    const renderDroneGroup = (droneCount: number, startX: number, fallStartFrameBase: number, seed: number, waitForBlast: boolean = false) => {
      return Array.from({ length: droneCount }).map((_, i) => {
        const baseX = startX + random(i + seed) * 500;
        const baseY = random(i + seed + 100) * 250 + 50; // Higher up
        
        let fallStartFrame = fallStartFrameBase + random(i + seed + 500) * 80; 
        
        // Compute wave collision if wait for blast is enabled
        if (waitForBlast) {
          const waveEmissionFrame = 130;
          const waveOriginX = width * 0.3 + waveEmissionFrame * boatSpeed + 10;
          const distanceToDrone = Math.max(0, baseX - waveOriginX);
          // Wave moves center by 600 and expands radius by 350 over 180 frames (~5.2px per frame leading edge speed)
          fallStartFrame = waveEmissionFrame + (distanceToDrone / 5.2) + random(i + seed + 500) * 15;
        }

        const isFalling = frame > fallStartFrame;
        const timeFalling = Math.max(0, frame - fallStartFrame);
        
        const driftX = Math.sin(frame * 0.01 + random(i + seed + 200) * 10) * 20;
        const hoverY = Math.cos(frame * 0.02 + random(i + seed + 300) * 10) * 15;
        
        // Ocean surface level
        const waterLevel = height * 0.75 + (random(i + seed + 400) * 60 - 30);
        const rawY = baseY + hoverY + (timeFalling * timeFalling * 0.35); 
        const hasHitWater = rawY >= waterLevel;
        
        const effectiveTime = hasHitWater ? Math.sqrt((waterLevel - (baseY + hoverY)) / 0.35) : timeFalling;
        
        // Sinks slightly after hitting the water
        const y = hasHitWater ? waterLevel + (timeFalling - effectiveTime) * 1.5 : rawY;
        const x = baseX + driftX + (isFalling ? (random(i + seed + 600) * 2 - 1) * effectiveTime * 0.8 : 0);
        const rotation = isFalling ? effectiveTime * (random(i + seed) > 0.5 ? 5 : -5) : 0;
        
        // Fade out into the ocean
        const opacity = hasHitWater ? Math.max(0, 1 - (timeFalling - effectiveTime) * 0.05) : 1;

        return (
          <g key={`drone-${seed}-${i}`} transform={`translate(${x}, ${y}) rotate(${rotation})`} opacity={opacity}>
            {/* Encapsulating Red Box (Top-Left and Bottom-Right Corners Only) */}
            <path 
              d="M -17 -12 L -25 -12 L -25 -4 M 25 5 L 25 13 L 17 13" 
              fill="none" 
              stroke="#FF0000" 
              strokeWidth={1.5} 
            />
            
            {/* Landing gear / legs */}
            <path d="M -3 2 L -5 8 M 3 2 L 5 8 M -6 8 L 6 8" stroke={droneColor} strokeWidth={1} fill="none" opacity={0.7} />
            
            {/* Arms */}
            <path d="M -4 0 L -14 -2 M 4 0 L 14 -2" stroke={droneColor} strokeWidth={2} fill="none" />
            
            {/* Motors */}
            <rect x="-16" y="-5" width="4" height="4" fill={droneColor} rx={1} />
            <rect x="12" y="-5" width="4" height="4" fill={droneColor} rx={1} />
            
            {/* Propellers (Spinning rapidly) */}
            <ellipse cx="-14" cy="-5" rx={Math.max(0.1, 7 * Math.abs(Math.cos(frame * 0.8 + i)))} ry="1" fill={droneColor} />
            <ellipse cx="14" cy="-5" rx={Math.max(0.1, 7 * Math.abs(Math.sin(frame * 0.8 + i)))} ry="1" fill={droneColor} />
            
            {/* Main Body */}
            <rect x="-6" y="-3" width="12" height="6" fill={droneColor} fillOpacity={0.25} stroke={droneColor} strokeWidth={1.5} rx={3} />
            
            {/* Camera/Sensor payload under body */}
            <circle cx="0" cy="3" r="2" fill={droneColor} />
            
            {/* Status Light (Blinking) */}
            <circle cx="-3" cy="-1" r="1" fill={(frame % 10 < 5) ? "#FFFFFF" : droneColor} />
          </g>
        );
      });
    };

    return (
      <g style={{ transition: "none" }}>
        {/* Left Drones (Struck by the first backwards blast) */}
        {renderDroneGroup(35, 50, 20, 0)}
        {/* Right Drones (Struck by the second forwards blast) -> Uses precise blast collision wave timing */}
        {renderDroneGroup(35, 1300, 140, 1000, true)}
      </g>
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      <svg 
        width="100%" 
        height="100%" 
        viewBox={`0 0 ${width} ${height}`} 
        style={{ position: "absolute", top: 0, left: 0 }}
      >
        {renderOcean()}
        {renderWaves()}
        {renderBoat()}
        {renderDrones()}
      </svg>
    </AbsoluteFill>
  );
};

export default JltvScene;